package com.client.multichatwindows.util; import com.client.multichatwindows.config.ConfigManager; import net.fabricmc.loader.api.FabricLoader; import java.nio.charset.StandardCharsets; import java.nio.file.*; import java.time.Instant; public final class DebugLog { private DebugLog(){} private static Path path(){return FabricLoader.getInstance().getConfigDir().resolve("multichatwindows").resolve("debug-log.txt");} public static void write(String content,String tabName,String reason){if(!ConfigManager.global().debug)return; try{String line="["+Instant.now()+"]\t"+tabName+"\t"+reason+"\t"+content+System.lineSeparator(); Files.createDirectories(path().getParent()); Files.writeString(path(),line,StandardCharsets.UTF_8,Files.exists(path())?StandardOpenOption.APPEND:StandardOpenOption.CREATE);}catch(Exception ignored){}} }
